contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testGrantApproval(address _logger) public {
        c.setApprovedLogger(_logger, true);
        assert(c.approvedToLog(_logger));
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function check(address caller) public {
        require(caller != address(this));
        bool ok;
        (ok, ) = address(c).call(
            abi.encodeWithSelector(c.setApprovedLogger.selector, caller, true)
        );
        assert(!ok && !c.approvedToLog(caller));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address keeper) public {
        require(keeper != address(0));
        bool unapproved = c.logCreated(keeper);
        require(!unapproved, "unapproved must not log");
        c.setApprovedLogger(keeper, true);
        bool approved = c.logCreated(keeper);
        assert(approved == c.approvedToLog(keeper));
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address unapprovedCaller, address keep) external {
        require(!c.approvedToLog(unapprovedCaller), "must be unapproved");
        bool r;
        r = c.call(abi.encodeWithSelector(bytes4(keccak256("logCreated(address)")), keep));
        require(r, "call failed");
        // A non-owner cannot approve anyone; c is controlled by its owner, not us,
        // so the caller (this contract) is unapproved.
        require(!c.approvedToLog(address(this)), "must be unapproved");
        bool ok = c.logCreated(keep);
        assert(!ok);
    }
}

contract InvMutTest {
    C private c;

    constructor(C _c) {
        c = _c;
    }

    function test(bool _approve, bytes32 _digest, bytes32 _r, bytes32 _s) public {
        c.setApprovedLogger(address(this), _approve);
        bool ret = c.logGotRedemptionSignature(_digest, _r, _s);
        assert(ret == _approve);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        bool obs = c.logCreated(address(this));
        assert(obs == c.approvedToLog(address(this)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _logger, bool _status, bytes32 _digest, bytes32 _r, bytes32 _s) public {
        require(true);
        c.setApprovedLogger(_logger, _status);
        bool approved = c.approvedToLog(_logger);
        bool obs = c.logGotRedemptionSignature(_digest, _r, _s);
        assert(obs != approved);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool _p, bytes32 _digest, bytes32 _r, bytes32 _s) public {
        require(true);

        // Branch 1: caller approved according to _p
        c.setApprovedLogger(address(this), _p);
        bool obs1 = c.logGotRedemptionSignature(_digest, _r, _s);

        // Branch 2: caller in the opposite approval state (!_p)
        c.setApprovedLogger(address(this), !_p);
        bool obs2 = c.logGotRedemptionSignature(_digest, _r, _s);

        // In P, logGotRedemptionSignature returns false in BOTH approval states:
        // approved callers return false (gated out), unapproved callers return false too.
        // In M, one of the two states (the unapproved one) returns true.
        assert(!obs1 && !obs2);
    }

    receive() external payable {}
}
